mapper.select:
SELECT cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', m.id 'monomer.id', m.name 'monomer.name', area.id 'area.id', area.name 'area.name', chage.*, r.`name` reason_name, u1.`name` user_name, u2.`name` handle_user_name FROM tech_artifact_change chage LEFT JOIN contract_project cp ON chage.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN plan_monomer m ON chage.monomer_id = m.id AND m.bool_delete_enum = 0 LEFT JOIN plan_area area ON chage.area_id = area.id AND area.bool_delete_enum = 0 LEFT JOIN sys_change_reason r ON chage.reason_id = r.id AND r.bool_delete_enum = 0 LEFT JOIN sys_user u1 ON chage.user_id = u1.id AND u1.bool_delete_enum = 0 LEFT JOIN sys_user u2 ON chage.handle_user_id = u2.id AND u2.bool_delete_enum = 0 WHERE chage.bool_delete_enum = 0
and chage.project_id = #{projectId}
and chage.monomer_id = #{monomerId}
and chage.area_id = #{areaId}
and chage.handle_status_enum = #{handleStatusEnum}
and chage.name like concat('%',#{name},'%')
and chage.serial_number like concat('%',#{serialNumber},'%')
and chage.serialNumber like concat('%',#{specification},'%')
and chage.reason_id = #{reasonId}
order by chage.handle_status_enum, chage.id desc

SELECT cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', m.id 'monomer.id', m.name 'monomer.name', area.id 'area.id', area.name 'area.name', ta.material, ta.length, chage.old_gross_weight, chage.new_gross_weight, chage.old_net_weight, chage.new_net_weight, chage.`name`, chage.serial_number, chage.specification, chage.user_id, chage.handle_user_id, chage.handle_time, chage.create_time, log.old_quantity oldQuantity, log.quantity newQuantity, log.old_quantity * chage.old_net_weight total_old_net_weight, log.quantity * chage.new_net_weight total_new_net_weight, r.`name` reason_name, u1.`name` user_name, u2.`name` handle_user_name FROM tech_artifact_change chage LEFT JOIN mes_building_change_log log ON log.change_id = chage.id AND log.type = 2 AND log.bool_delete_enum = 0 left join tech_artifact ta on chage.artifact_id = ta.id LEFT JOIN contract_project cp ON chage.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN plan_monomer m ON chage.monomer_id = m.id AND m.bool_delete_enum = 0 LEFT JOIN plan_area area ON chage.area_id = area.id AND area.bool_delete_enum = 0 LEFT JOIN sys_change_reason r ON chage.reason_id = r.id AND r.bool_delete_enum = 0 LEFT JOIN sys_user u1 ON chage.user_id = u1.id AND u1.bool_delete_enum = 0 LEFT JOIN sys_user u2 ON chage.handle_user_id = u2.id AND u2.bool_delete_enum = 0 WHERE chage.bool_delete_enum = 0 AND log.id is not null
and chage.project_id = #{projectId}
and chage.monomer_id = #{monomerId}
and chage.area_id = #{areaId}
and chage.handle_status_enum = #{handleStatusEnum}
and chage.name like concat('%',#{name},'%')
and chage.serial_number like concat('%',#{serialNumber},'%')
and chage.serialNumber like concat('%',#{specification},'%')
and chage.reason_id = #{reasonId}
and chage.create_time >= #{startDate}
and chage.create_time <= #{endDate}
order by chage.handle_status_enum, chage.id desc

SELECT c.* FROM tech_artifact_change c, ( SELECT artifact_id, max(handle_time) handle_time FROM tech_artifact_change WHERE bool_delete_enum = 0 AND handle_status_enum = 2 AND ( ( old_net_weight != new_net_weight OR old_gross_weight != new_gross_weight or old_quantity != new_quantity) OR id IN ( SELECT change_id FROM mes_building_change_log WHERE bool_delete_enum = 0 ) ) GROUP BY artifact_id ) b, tech_artifact art WHERE c.artifact_id = b.artifact_id AND c.handle_time = b.handle_time AND c.artifact_id = art.id
AND art.project_id = #{projectId}
AND art.monomer_id = #{monomerId}
AND art.area_id = #{areaId}
AND art.serial_number Like concat('%',#{serialNumber},'%')
AND art.specification Like concat('%',#{specification},'%')
AND art.`name` like concat('%',#{name},'%')
and date(c.handle_time) >= date(#{startDate})
and date(c.handle_time) <= date(#{endDate})
